function effectMarkup(fx){let family=['explosion','lightning','fireworks','flames','ice','electric','confetti','sparks','neon','smoke','stars','meteor','rainbow','shockwave','laser','portal','thunder','embers','snow','pixels','glitch','hearts','diamonds','green','purple','alert','nova','gold','silver','plasma','comet','dragon','runes','ghost','shadow','sun','moon','tornado','water','bubbles','petals','leaves','disco','spotlight','flash','crown','victory','firering','vortex','supernova'][fx-1]||'explosion';let particles=Array.from({length:34},(_,n)=>`<i style="--n:${n};--x:${(n*37)%101};--y:${(n*61)%101};--r:${(n*47)%360}"></i>`).join('');let extra=family==='lightning'||family==='electric'||family==='thunder'?'<svg class="fx-svg fx-lightning-svg" viewBox="0 0 100 100" preserveAspectRatio="none"><path d="M54 0 35 43h17L39 100l32-55H54L72 0Z"/><path d="M18 8 8 39h10L10 67l24-36H23L36 8Z"/><path d="m84 15-12 29h10L73 76l22-39H85l9-22Z"/></svg>':family==='ice'?'<div class="fx-ice-cracks"></div><div class="fx-frost"></div>':family==='water'?'<div class="fx-water-wave w1"></div><div class="fx-water-wave w2"></div><div class="fx-water-splash"></div>':family==='flames'||family==='dragon'||family==='firering'?'<div class="fx-fire-core"></div>':family==='explosion'||family==='supernova'?'<div class="fx-blast-core"></div>':'';return `<div class="fx-layer fx-kind-${family}" data-effect="${fx}" aria-hidden="true">${introCanvasMarkup(fx)}${effectScene(fx)}${particles}<b></b><em></em>${extra}</div>`}
function introEffectPreview(effect=profile.introEffect||'fx1'){let fx=Math.max(1,Math.min(50,Number(String(effect).replace('fx',''))||1)),name=introEffectNames[fx-1];return `<div id="introEffectPreview" class="intro-preview intro-fx fx-${fx}">${effectMarkup(fx)}<div class="intro-preview-content">${avatar(profile,true)}<strong>${esc(profile.name||'YOUR TEAM')}</strong></div></div>`}
function refreshIntroEffectPreview(effect){let old=$('#introEffectPreview');if(!old)return;let box=document.createElement('div');box.innerHTML=introEffectPreview(effect);old.replaceWith(box.firstElementChild);requestAnimationFrame(startIntroCanvases)}
function profileForm(){let preset=profile.themePreset||(!profile.theme?'preset:1':'');let used=new Set([...claimedThemeSet(),...(state?.players||[]).filter(p=>p.id!==state?.me?.id).map(p=>p.themePreset).filter(Boolean)]);return `<label>Team Name<input id="playerName" maxlength="24" value="${esc(profile.name)}" placeholder="What should Lex call you?" autocomplete="nickname"></label><div class="profile-preview">${avatar(profile,true)}<div><strong>Your player portrait</strong><p class="muted">Choose an avatar or add a photo.</p></div></div><div class="avatar-list">${avatars.map((a,i)=>`<button data-act="avatar" data-i="${i}" class="${!profile.photo&&profile.avatar===i?'selected':''}" aria-label="Choose ${a} avatar">${a}</button>`).join('')}</div><label>Upload or take a photo<input id="photoInput" type="file" accept="image/*"></label>${profile.photo?'<button class="ghost full" data-act="removePhoto">Use an avatar instead</button>':''}<div class="theme-choice"><label>✨ Player introduction effect<select id="introEffect">${introEffectOptions(profile.introEffect||'fx1')}</select></label></div>${introEffectPreview(profile.introEffect||'fx1')}<button type="button" class="primary full intro-preview-play" data-act="previewIntro">▶ Preview full entrance — effect + sound + theme</button><p class="muted">Preview the exact entrance before the quiz: your photo, team name, visual effect, matching effect sound and chosen theme music together.</p><div class="theme-choice"><label>🎵 Choose a built-in fastest-answer theme<select id="themePreset"><option value="">Upload my own instead</option>${themeOptions(preset,used)}</select></label><button type="button" data-act="previewTheme">▶ Preview built-in theme</button></div><div class="divider"></div><label>Or upload your own audio<input id="themeInput" type="file" accept="audio/*"></label><p class="muted">120 built-in victory stingers are included, or choose a short audio clip (about 10 seconds, under 1 MB). Your choice plays when you are first correct.</p>${profile.theme||profile.themePreset?'<button class="ghost full" data-act="removeTheme">Clear my theme</button>':''}`}
function home(){let history=storage.get('history',[]);return `<section class="hero"><div><span class="eyebrow">YOUR PEOPLE. YOUR QUIZ. YOUR NIGHT.</span><h1>A little knowledge.<br>A lot of <em>chaos.</em></h1><p class="lead">Gather the gang. Grab your phones. I’m Lex, and I’ll take it from here.</p><div class="actions"><button class="primary" data-act="setup">Host a quiz ↗</button><button data-act="joinPage">Join a room</button></div><div class="actions"><button class="ghost" data-act="profilePage">👤 My Player Profile</button><button class="ghost" data-act="demo">Try a solo demo</button>${session?'<button class="gold" data-act="resume">Resume my room</button>':''}</div><p class="muted">Up to 100 players · No downloads · Optional TV screen</p>${!backend?'<div class="notice">The solo demo is ready. Live room codes need the multiplayer server connected. Open ⚙ to connect it after deployment.</div>':''}</div><div class="card lex-card">${face(true)}<div class="lex-mark"><div><div class="lex-name">LEX</div><div class="lex-tag">YOUR HOST & CHAOS COMPANION</div></div></div><p class="lex-speech">“Alright, buddy. Think you know it all? Let’s put that to the test.”</p><div class="mini-pills"><span>🎤 OPTIONAL VOICE</span><span>🃏 SECRET POWER CARDS</span><span>🏆 ONE BRAGGING-RIGHTS WINNER</span></div></div></section><div class="section-title"><h2>Pick your playground</h2><span class="muted">16 categories</span></div><div class="category-strip">${D.categories.map((c,i)=>`<span>${icons[i]} ${esc(c)}</span>`).join('')}</div><div class="section-title"><h2>Keep everyone guessing</h2><span class="muted">11 round types</span></div><div class="mode-grid">${Object.entries(E.modes).map(([k,m])=>`<div class="card mode-tile"><span class="icon">${m.icon}</span><h3>${m.name}</h3><p>${m.desc}</p></div>`).join('')}</div>${history.length?`<div class="section-title"><h2>Your recent quiz nights</h2></div><div class="card">${history.slice(0,5).map(h=>`<div class="history-row"><span>${esc(h.date)} · ${esc(h.name)}</span><strong>${h.score} pts · #${h.rank}</strong></div>`).join('')}</div>`:''}<p class="footer-note">Cadoops Quiz v1.0 · Made for Leon, Coops and the gang · Hosted by Lex</p>`}
const soloNameA=['Captain','Professor','Doctor','Sir','Lady','Lord','Agent','Major','Mister','Miss','Quiz','Trivia','Brainy','Lucky','Sneaky','Mighty','Tiny','Mega','Ultra','Turbo','Cosmic','Mystic','Pixel','Retro','Neon','Disco','Chaos','Cheeky','Grumpy','Sleepy','Spicy','Crispy','Soggy','Wobbly','Barmy','Bonkers','Dodgy','Fancy','Funky','Ninja','Wizard','Pirate','Viking','Zombie','Ghost','Dragon','Goblin','Jedi','Hobbit','Ranger','Knight','Detective','Sheriff','Boss','King','Queen'];
const soloNameB=['Baggins','Skywalker','Kenobi','Potter','Granger','Weasley','Gandalf','Aragorn','Legolas','Stark','Targaryen','Lannister','Batman','Robin','Joker','Flash','Thor','Loki','Groot','Rocket','Wolverine','Deadpool','Pikachu','Charizard','Kirby','Link','Zelda','Mario','Luigi','Yoshi','Bowser','Sonic','Tails','Kratos','Geralt','Ezio','Pacman','Ryu','Crash','Spyro','Doomguy','MasterChief','LaraCroft','Sherlock','Watson','Bond','Rocky','Rambo','Ripley','McClane','Maverick','Shrek','Donkey','Gollum','Dobby','Yoda','Chewbacca','Godzilla','Kong','Dracula','Frankenstein','Merlin','RobinHood','PeterPan','Tinkerbell','Scooby','Shaggy','Garfield','Snoopy','Paddington','WillyWonka','AceVentura','Beetlejuice','Terminator','Predator','Alien','Gremlin','Muppet','Dalek','Tardis','BasilFawlty','Blackadder','MrBean','DelBoy','Trigger','AlanPartridge','Homer','Bart','Bender','Fry','Cartman','Kenny','Dwight','Chandler','Joey','Phoebe','Buffy','Mulder','Scully','Dexter','WalterWhite','SaulGoodman','Eleven','Wednesday','TedLasso','PeakyBlinder','DoctorWho','Fox','Owl','Panda','Tiger','Otter','Raven','Wolf','Shark','Falcon','Badger','Lynx','Gecko','Koala','Cobra','Mantis','Moose','Penguin','Rabbit','Turtle','Squirrel','Shrimp','Cat','Pigeon','Duck','Goose','Potato','Turnip','Nugget','Pickle','Waffle','Biscuit','Crumpet','Teabag','Sausage','Meatball','Custard','Gravy','Cheese','Beans','Toast','Kebab','Chippy','Marmite'];
const soloNameC=['Brain','Buzzer','Bandit','Boffin','Master','Machine','Wizard','Warrior','Warlord','Champion','Legend','Menace','Gremlin','Goblin','Ninja','Knight','King','Queen','Lord','Boss','Beast','Monster','Muppet','Maniac','Genius','Guess','Goat','Potato','Pants','Face','Head','McQuizface','KnowItAll','NoClue','WildCard','PointThief','FactHunter','AnswerGoblin','TriviaTitan','Quizzer','Brainbox'];
const soloPunNames=['Quiztopher Walken','Quiz Hemsworth','Quizzy McGuire','Agatha Quiztie','Quiz Khalifa','Quizteama Aguilera','Sherlock Homie','Smarty Pints','Victorious Secret','Universally Challenged','Risky Quizness','No Eye Deer','The Know It Owls','Guess Who','Ctrl Alt Defeat','404 Answer Not Found','Fact Hunt','The Last Brain Cell','One Braincell Left','Certified Guess Merchant','Professional Button Masher','Definitely Not Googling','I Came For Snacks','Ask Me Tomorrow','Educated Guess','Confidently Incorrect','The Point Goblin','Buzzer Beater','Quiz In My Pants','Lord Of The Answers','Game Of Phones','The Fast And The Curious','Silence Of The Hams','Indiana Clueless','Jurassic Spark','Obi Wan Quiznobi','Han Solo Score','Darth Tater','Gandalf The Guess','You Shall Not Guess','The Quizfather','Quiz Hard','Quiz Actually','Quiz Story','Finding Answers','Pirates Of The Quizibbean','Beauty And The Brain','The Good The Bad And The Quizzy','Stranger Answers','Breaking Brain','Better Call Lex','Only Fools And Answers','Who Wants A Biscuit','Master Of None','Brainy McBrainface','Captain Guesswork','General Knowledge Kenobi'];
function randomSoloName(){if(Math.random()<.3)return soloPunNames[Math.floor(Math.random()*soloPunNames.length)];let a=soloNameA[Math.floor(Math.random()*soloNameA.length)],b=soloNameB[Math.floor(Math.random()*soloNameB.length)],c=soloNameC[Math.floor(Math.random()*soloNameC.length)],mode=Math.floor(Math.random()*5);return [a+' '+b,b+' '+c,a+' '+c,a+' '+b+' '+c,b+' The '+c][mode].slice(0,24)}
function makeSoloRoster(count){count=Math.max(1,Math.min(100,Number(count)||8));let mine=profile.themePreset||'',pool=['real:ace','real:finalfantasy','real:spongebob',...Array.from({length:120},(_,i)=>'preset:'+(i+1))].filter(id=>id!==mine&&!claimedThemeSet().has(id)),takenNames=new Set([(profile.name||'You').trim().toLowerCase()]);soloRoster=Array.from({length:count},(_,i)=>{if(i===0)return {...profile,name:profile.name||'You'};let name='',tries=0;do{name=randomSoloName();tries++}while(takenNames.has(name.toLowerCase())&&tries<500);if(takenNames.has(name.toLowerCase()))name=('Player '+(i+1)+' '+Math.random().toString(36).slice(2,7)).slice(0,24);takenNames.add(name.toLowerCase());return {name,avatar:Math.floor(Math.random()*avatars.length),photo:'',theme:'',themePreset:pool.splice(Math.floor(Math.random()*pool.length),1)[0]||''}});draft.soloPlayers=count}
function soloPlayersPage(){if(!soloRoster.length)makeSoloRoster(draft.soloPlayers||8);return `<div class="page-heading"><div><span class="eyebrow">SOLO SIMULATION</span><h1>Build your player roster.</h1><p class="lead">Choose up to 100 simulated players. Random profiles are ready to use, or customise any player.</p></div><button data-act="home" class="ghost">← Home</button></div><section class="card"><div class="fields"><label>Number of players (1–100)<input id="soloCount" type="number" min="1" max="100" value="${soloRoster.length}"></label><button class="gold" data-act="generateSoloRoster">Generate / resize roster</button></div></section><div class="players-grid solo-roster">${soloRoster.map((p,i)=>`<div class="player-tile">${avatar(p)}<div><strong>${esc(p.name)}</strong><div class="muted">${i===0?'You':'Simulated player'} · ${p.themePreset?esc(themeNames[Number(p.themePreset.split(':')[1])-1]||'Built-in theme'):'Custom theme'}</div></div><button data-act="editSoloPlayer" data-i="${i}">Edit</button></div>`).join('')}</div><div class="actions" style="margin-top:22px"><button class="primary" data-act="startSoloRoster">Start solo game ▶</button><button data-act="soloContinue">Back to quiz setup</button></div>`}
function soloPlayerEditor(i){let p=soloRoster[i];if(!p)return soloPlayersPage();let used=new Set(soloRoster.map((x,j)=>j===i?'':x.themePreset).filter(Boolean));return `<div class="page-heading"><div><span class="eyebrow">PLAYER ${i+1}</span><h1>Customise ${esc(p.name)}.</h1></div><button data-act="soloRosterBack" class="ghost">← Roster</button></div><section class="card" style="max-width:720px;margin:0 auto"><label>Player name<input id="soloName" maxlength="24" value="${esc(p.name)}"></label><div class="profile-preview">${avatar(p,true)}<div><strong>Player portrait</strong><p class="muted">Choose an avatar or upload a photo.</p></div></div><div class="avatar-list">${avatars.map((a,j)=>`<button data-act="soloAvatar" data-player="${i}" data-i="${j}" class="${!p.photo&&p.avatar===j?'selected':''}">${a}</button>`).join('')}</div><label>Upload or take a photo<input id="soloPhotoInput" data-player="${i}" type="file" accept="image/*"></label>${p.photo?`<button class="ghost full" data-act="soloRemovePhoto" data-player="${i}">Use an avatar instead</button>`:''}<div class="theme-choice"><label>🎵 Built-in theme<select id="soloThemePreset" data-player="${i}"><option value="">Upload my own instead</option>${themeOptions(p.themePreset,used)}</select></label><button data-act="soloPreviewTheme" data-player="${i}">▶ Preview</button></div><label>Or upload custom audio<input id="soloThemeInput" data-player="${i}" type="file" accept="audio/*"></label><button class="primary full" data-act="saveSoloPlayer" data-player="${i}" style="margin-top:20px">Save player</button></section>`}
function playerProfilePage(){return `<div class="page-heading"><div><span class="eyebrow">YOUR PLAYER IDENTITY</span><h1>My Player Profile.</h1><p class="lead">Set the name, picture and entrance music everyone sees when you’re fastest correct.</p></div><button data-act="home" class="ghost">← Home</button></div><div class="card profile-editor" style="max-width:720px;margin:0 auto">${profileForm()}<div class="actions" style="margin-top:22px"><button class="primary full" data-act="saveProfilePage">Save my profile</button></div></div>`}
function setup(){return `<div class="page-heading"><div><span class="eyebrow">THE NIGHT STARTS HERE</span><h1>Build your quiz.</h1></div><div class="actions"><button data-act="profilePage" class="ghost">👤 Player Profile</button><button data-act="home" class="ghost">← Back</button></div></div><div class="setup-layout"><div class="stack"><section class="card"><h2>Set the vibe</h2><div class="segmented"><button data-act="play" data-play="random" class="${draft.play==='random'?'selected':''}">🎲 Random quiz</button><button data-act="play" data-play="custom" class="${draft.play==='custom'?'selected':''}">🛠 Custom quiz</button></div><p class="muted">${draft.play==='random'?'Lex shuffles a variety of rounds from your selected categories. Music is included when matching clips are uploaded.':'Choose your rounds, their order and categories. Mix things up however you like.'}</p><section class="card solo-options"><h2>Solo game players</h2><label>How many players should Lex simulate? (1–100)<input id="soloPlayers" type="number" min="1" max="100" value="${draft.soloPlayers}"></label><p class="muted">You are one of these players. Everyone else gets a random name, avatar and unique theme.</p><div class="divider"></div><h3>Your player profile</h3>${profileForm()}</section><div class="fields"><label>Player limit (1–100)<input id="capacity" type="number" min="1" max="100" value="${draft.capacity}"></label><label>Seconds per question<input id="seconds" type="number" min="5" max="120" value="${draft.seconds}"></label>${draft.play==='random'?`<label>Number of rounds<input id="roundCount" type="number" min="1" max="11" value="${draft.roundCount}"></label><label>Questions per round<input id="perRound" type="number" min="1" max="10" value="${draft.perRound}"></label>`:''}</div><label class="switch"><input type="checkbox" id="auto" ${draft.auto?'checked':''}> Advance automatically after answer reveals</label><p class="muted">Bingo has 9 clues per card. Final Showdown always gives 8 seconds per question. Lex’s intro and the question are shown together.</p></section><section class="card"><div class="section-title" style="margin-top:0"><h2>Categories</h2><button data-act="allCats" class="ghost">${draft.categories.length===16?'Clear':'All'}</button></div><div class="categories">${D.categories.map((c,i)=>`<button data-act="cat" data-cat="${esc(c)}" class="category-btn ${draft.categories.includes(c)?'selected':''}"><span>${icons[i]}</span>${esc(c)}</button>`).join('')}</div></section>${draft.play==='custom'?`<section class="card"><h2>Your running order</h2><div id="rounds">${draft.rounds.map((r,i)=>`<div class="round-row"><div class="round-fields"><select data-round="${i}" data-key="mode">${Object.entries(E.modes).map(([k,m])=>`<option value="${k}" ${r.mode===k?'selected':''}>${i+1}. ${m.icon} ${m.name}</option>`).join('')}</select><select class="round-category" data-round="${i}" data-key="category"><option>Mixed</option>${draft.categories.map(c=>`<option ${r.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select><input data-round="${i}" data-key="count" aria-label="Questions in round ${i+1}" type="number" min="1" max="20" value="${r.mode==='bingo'?8:r.count}" ${r.mode==='bingo'?'disabled':''}><button data-act="deleteRound" data-i="${i}" aria-label="Remove round ${i+1}">✕</button></div><p class="muted">${E.modes[r.mode].desc}</p><div class="actions" style="margin-top:8px"><button class="ghost" data-act="moveRound" data-i="${i}" data-dir="-1" ${i===0?'disabled':''}>↑</button><button class="ghost" data-act="moveRound" data-i="${i}" data-dir="1" ${i===draft.rounds.length-1?'disabled':''}>↓</button></div></div>`).join('')}</div><button class="full" style="margin-top:16px" data-act="addRound" ${draft.rounds.length>=20?'disabled':''}>＋ Add a round</button></section>`:''}<details><summary>🎵 Add music clips (${draft.songs.length})</summary><p class="muted">Upload short clips below 2 MB each. The host/TV plays the audio; phones provide buzzers. Use clips you can share. Set the category to match your quiz selection.</p><div class="fields"><label>Song title<input id="songTitle" maxlength="150"></label><label>Artist<input id="songArtist" maxlength="150"></label></div><label>Other accepted titles (separate with |)<input id="songAliases" placeholder="Alternative title | Short title"></label><label>Category<select id="songCategory">${D.categories.map(c=>`<option>${esc(c)}</option>`).join('')}</select></label><label>Audio clip<input id="songFile" type="file" accept="audio/*"></label><button data-act="addSong">Add clip</button>${draft.songs.map((s,i)=>`<div class="media-item"><span>${esc(s.answer)} — ${esc(s.artist)} · ${esc(s.category)}</span><button data-act="removeSong" data-i="${i}">✕</button></div>`).join('')}</details><details><summary>🖼 Add picture questions (${draft.pictures.length})</summary><p class="muted">Built-in pictures cover General Knowledge flags and shapes. Add your own pictures for any category. Photos are compressed before upload.</p><label>Question<input id="picturePrompt" placeholder="Who is this character?"></label><label>Correct answer<input id="pictureAnswer"></label><div class="fields">${[1,2,3].map(i=>`<label>Wrong answer ${i}<input id="wrong${i}"></label>`).join('')}</div><label>Category<select id="pictureCategory">${D.categories.map(c=>`<option>${esc(c)}</option>`).join('')}</select></label><label>Picture<input id="pictureFile" type="file" accept="image/*"></label><button data-act="addPicture">Add picture</button>${draft.pictures.map((s,i)=>`<div class="media-item"><span>${esc(s.prompt)} · ${esc(s.category)}</span><button data-act="removePicture" data-i="${i}">✕</button></div>`).join('')}</details></div><aside class="card sticky"><h3>Your host profile</h3><label class="switch"><input type="checkbox" id="hostPlays" ${draft.hostPlays?'checked':''}> I’m playing too</label>${profileForm()}<div class="divider"></div><div class="lex-mark">${face()}<div><strong>Lex has the mic.</strong><p class="muted">Everyone can play. You keep pause and score controls.</p></div></div><button class="primary full" data-act="create" style="margin-top:20px" ${busy?'disabled':''}>${busy?'Creating your room…':'Create live room ↗'}</button><button class="ghost full" data-act="demoSetup" style="margin-top:8px">Try this setup solo</button><p class="muted">Questions are chosen without repeats within the same question pool. If a pack is too small, Lex will explain what needs changing.</p><div id="setupError"></div></aside></div>`}
function readDraft(){['capacity','seconds','roundCount','perRound','soloPlayers'].forEach(k=>{if($('#'+k))draft[k]=Number($('#'+k).value)});['auto','hostPlays'].forEach(k=>{if($('#'+k))draft[k]=$('#'+k).checked});saveProfile()}
function join(){let tv=page==='tvjoin';return `<div class="join-layout"><span class="eyebrow">${tv?'THE BIG SCREEN':'YOU’RE INVITED'}</span><h1>${tv?'Open TV view.':'Join the gang.'}</h1><div class="card"><label>Room code<input id="roomCode" maxlength="6" autocapitalize="characters" autocomplete="off" value="${esc(params.get('room')||'')}" placeholder="ABC123" style="text-transform:uppercase;letter-spacing:5px;font-size:24px"></label>${tv?'':profileForm()}<button class="primary full" data-act="join" style="margin-top:20px" ${busy?'disabled':''}>${busy?'Joining…':tv?'Open shared screen':'Join quiz ↗'}</button><div id="joinError"></div></div><div class="actions"><button class="ghost" data-act="home">← Home</button><button class="ghost" data-act="toggleTv">${tv?'Join as a player instead':'Open as TV / shared screen'}</button></div></div>`}
function lexLine(){return `<div class="lex-inline">${face()}<div><small>LEX · YOUR QUIZ HOST</small><p>${esc(state.message)}</p></div></div>`}
function roomBanner(){return `<div class="room-banner"><div><span class="eyebrow">${local?'SOLO DEMO · NOT A LIVE ROOM':'ROOM CODE · '+state.players.length+'/'+state.capacity+' PLAYERS'}</span><div class="room-code">${local?'DEMO':esc(state.code)}</div></div><div class="actions">${!local?'<button data-act="copyInvite">Copy invite</button><button data-act="tv">TV view ↗</button>':''}<button class="ghost" data-act="leave">Leave</button></div></div>`}
function lobby(){return `${roomBanner()}${lexLine()}<div class="lobby-layout"><div class="card"><div class="section-title" style="margin-top:0"><h2>The gang’s all here.</h2><span class="pill">${state.players.length} READY</span></div><p class="muted">${session?.hostToken?'Share the room code or invite link. Start when everyone has joined.':'You’re in! Lex is waiting for the host to start.'}</p><div class="players-grid">${state.players.map(p=>`<div class="player-tile">${avatar(p)}<div><strong>${esc(p.name)}</strong><div class="muted">Ready to play</div></div>${session?.hostToken?`<button data-act="kick" data-id="${p.id}" aria-label="Remove ${esc(p.name)}">✕</button>`:''}</div>`).join('')}</div>${!state.players.length?'<div class="empty">Waiting for the first player…</div>':''}</div><aside class="card"><span class="eyebrow">TONIGHT’S LINEUP</span><h2 style="margin-top:14px">${state.total} questions.<br>One crown.</h2><p class="muted">Private answers, live scores and a little Cadoops chaos. ${state.auto?'Lex advances automatically.':'The host controls the pace.'}</p>${session?.hostToken?`<button class="gold full" data-act="start" ${!state.players.length?'disabled':''}>Start quiz ▶</button>${!session.playerToken?'<button class="full" data-act="hostJoin" style="margin-top:10px">Join as a player too</button>':''}`:'<div class="notice">Waiting for the host to start.</div>'}<button class="ghost full" data-act="enableVoice" style="margin-top:10px">${prefs.voice?'🔊 Lex voice is on':'🎤 Let Lex speak here'}</button><p class="muted">Use voice on just one screen if you’re in the same room.</p></aside></div>`}
function leaderboard(full=false){let sorted=[...state.players].sort((a,b)=>b.score-a.score);return `<div class="scoreboard">${sorted.slice(0,full?100:10).map((p,i)=>`<div class="score-row ${p.id===state.me?.id?'me':''}"><span class="rank">${i+1}</span>${avatar(p)}<span class="name">${esc(p.name)}${p.submitted&&state.phase==='question'?' ✓':''}</span><div><span class="score">${p.score}</span>${p.answer?.delta?`<div class="delta ${p.answer.delta<0?'negative':''}">${p.answer.delta>0?'+':''}${p.answer.delta}</div>`:''}</div></div>`).join('')}</div>${!full&&sorted.length>10?'<button class="ghost full" data-act="allScores" style="margin-top:10px">See all '+sorted.length+' players</button>':''}`}
function targetButtons(action,ordered=false){let players=ordered&&state.pendingSteal?.targets?state.pendingSteal.targets.map(pid=>state.players.find(p=>p.id===pid)).filter(Boolean):state.players.filter(p=>p.id!==state.me?.id);return `<div class="target-picker"><p>Choose a team</p><div class="target-buttons">${players.map(p=>`<button type="button" data-act="${action}" data-target="${p.id}">${esc(p.name)}</button>`).join('')}</div></div>`}
function controls(){return session?.hostToken?`<div class="host-controls"><button data-act="pause">${state.paused?'▶ Resume':'⏸ Pause'}</button>${state.phase==='question'?'<button data-act="reveal">Reveal / skip</button>':'<button class="gold" data-act="next">Next question →</button>'}<button data-act="adjust">Correct a score</button><label class="switch"><input id="gameAuto" type="checkbox" ${state.auto?'checked':''}> Auto advance</label></div>`:''}
function alphabetPad(disabled=false){let picked=String(state?.me?.answer?.value??'').toUpperCase(),keys=[...'ABCDEFGHIJKLMNOPQRSTUVWXYZ'];return '<div class="alphabet-pad">'+keys.map(l=>`<button class="${picked===l?'answer-picked':''}" data-act="answer" data-value="${l}" ${disabled?'disabled':''}>${l}</button>`).join('')+'</div>'}
function numberPad(disabled=false){return `<div class="number-entry"><input id="numericAnswer" type="number" inputmode="numeric" step="any" placeholder="Your number" ${disabled?'disabled':''}><div class="number-pad">${[1,2,3,4,5,6,7,8,9,0].map(n=>`<button type="button" data-act="numKey" data-value="${n}" ${disabled?'disabled':''}>${n}</button>`).join('')}<button type="button" data-act="numBack" ${disabled?'disabled':''}>⌫</button><button class="gold" data-act="numberAnswer" ${disabled?'disabled':''}>ENTER</button></div></div>`}
function answerArea(){let q=state.q,me=state.me,reveal=state.phase==='reveal',reading=state.phase==='reading';if(session.tv)return `<p class="progress-note">${reveal?'Answers revealed on everyone’s phones.':'Answer on your phone · '+state.players.filter(p=>p.submitted).length+'/'+state.players.length+' answers locked'}</p>`;if(!me)return '<div class="notice">You’re watching as the host. Players answer on their phones.</div>';
let locked=!!me.answer||state.paused||reveal||reading;
let extra='';
if(q.mode==='bet'&&!locked){let own=state.players.find(p=>p.id===me.id);extra=`<label>Your stake (0–${Math.min(500,own.score)})<input id="stake" type="number" min="0" max="${Math.min(500,own.score)}" value="0"></label>`}
if(q.mode==='chaos'){let card={double:['✖️ Double','Double your points if this answer is correct.'],shield:['🛡 Shield','Protect yourself from a Steal on this question.'],steal:['🦹 Steal','If your answer is correct, steal 5 points from a rival.']}[me.card];extra=`<div class="power"><strong>Your secret card: ${card[0]}</strong><p>${card[1]} Answer first — then decide whether to use it.</p>${me.cardUsed?`<span class="muted">Card locked in for this question.</span>`:me.answer&&!reveal?(me.card==='steal'?targetButtons('chaosSteal'): `<button data-act="power">Use ${card[0]} now</button>`):!me.answer&&!reveal?'<span class="muted">Answer the question first. Your card will unlock afterwards.</span>':''}</div>`}
if(q.mode==='bingo')return `<p class="muted">Find the answer on your card. One attempt per clue.</p><div class="bingo-grid">${me.grid.map((v,i)=>`<button data-act="answer" data-value="${esc(v)}" class="${me.marks.includes(i)?'marked':''}" ${locked?'disabled':''}>${me.marks.includes(i)?'✓ ':''}${esc(v)}</button>`).join('')}</div>`;
if(q.mode==='closest')return numberPad(locked)+(me.answer&&!reveal?'<div class="locked">✓ Guess submitted.</div>':'');
if(q.mode==='music'){if(reveal)return '';let winner=state.players.find(p=>p.id===state.buzz?.id);if(me.answer)return '<div class="locked">Your attempt is locked.</div>';if(state.buzz?.id===me.id)return `<div class="notice">You buzzed first! <span id="buzzTime"></span>s</div><label>Song title<input id="musicTitle"></label><label>Artist<input id="musicArtist"></label><button class="primary full" data-act="musicAnswer">Submit</button>`;return `<button class="buzz-button" data-act="buzz" ${locked||state.buzz?'disabled':''}>${winner?esc(winner.name)+' buzzed!':'BUZZ!'}</button>`}
if(q.mode==='buzzer'){if(reveal)return '';let winner=state.players.find(p=>p.id===state.buzz?.id);if(me.answer)return '<div class="locked">Your one attempt is locked.</div>';if(state.buzz?.stage==='entrance')return '';if(state.buzz?.id===me.id)return `<div class="notice">🚨 YOUR 5 SECONDS START NOW — <span id="buzzTime"></span>s</div>${alphabetPad(false)}`;return `<button class="buzz-button" data-act="buzz" ${locked||state.buzz?'disabled':''}>${winner?esc(winner.name)+' BUZZED!':'BUZZ!'}</button><p class="muted">Only the first team to buzz gets an attempt.</p>`}
if(q.mode==='quote')return `${extra}<p class="muted">Choose the person or character who said the quote.</p><div class="answer-grid">${q.options.map(v=>`<button class="answer-option ${String(me.answer?.value??'')===String(v)?'answer-picked':''}" data-act="answer" data-value="${esc(v)}" ${locked?'disabled':''}>${esc(v)}</button>`).join('')}</div>`;
if(['clue','whoami','connections'].includes(q.mode))return `${extra}<p class="muted">${q.mode==='whoami'?'🕵️ Who am I?':q.mode==='connections'?'🧩 Find the connection':'🔎 Use Lex’s clue'} — choose from four answers.</p><div class="answer-grid">${q.options.map(v=>`<button class="answer-option ${String(me.answer?.value??'')===String(v)?'answer-picked':''}" data-act="answer" data-value="${esc(v)}" ${locked?'disabled':''}>${esc(v)}</button>`).join('')}</div>`;
if(q.mode==='higher')return `${extra}<div class="answer-grid">${q.options.map(v=>`<button class="answer-option ${String(me.answer?.value??'')===String(v)?'answer-picked':''}" data-act="answer" data-value="${esc(v)}" ${locked?'disabled':''}>${esc(v)}</button>`).join('')}</div>`;
return `${extra}<p class="muted">Tap the first letter of the answer. Your tap submits instantly.</p>${alphabetPad(locked)}${me.answer&&!reveal?'<div class="locked">✓ Answer submitted.</div>':''}`}
function roundIntro(){let q=state.q,m=E.modes[q.mode];return `<section class="round-intro"><div class="round-intro-icon">${m.icon}</div><p class="eyebrow">ROUND ${q.round} OF ${q.roundTotal}</p><h1>${esc(m.name)}</h1><div class="round-rules"><h3>How this round works</h3><p>${esc(m.desc)}</p><p><strong>${q.roundSize}</strong> question${q.roundSize===1?'':'s'} in this round.</p></div>${session?.hostToken?'<button class="primary round-start" data-act="startRound">Start round →</button>':'<div class="notice">Listen to Lex — the host will start the round when everyone is ready.</div>'}</section>`}
function playerIntro(){let i=state.introIndex??0,p=state.players[i]||state.players[0],fx=Math.max(1,Math.min(50,Number(String(p.introEffect||'fx1').replace('fx',''))||1)),name=introEffectNames[fx-1];return `<div class="player-intro intro-fx fx-${fx}">${effectMarkup(fx)}${avatar(p,true)}<h1>${esc(p.name)}</h1></div>`}
async function startPlayerIntroductions(){if(!local&&session?.code){try{let fresh=await request('/api/rooms/'+session.code);if(fresh?.players)state=fresh}catch(e){throw new Error('Could not confirm the player list before starting. '+e.message)}}if(!state?.players?.length)throw new Error('No players are in the room yet.');await action('host',{action:'start'})}
function runPlayerIntro(){let p=state?.players?.[introIndex];if(!p){introIndex=-1;introUntil=0;action('host',{action:'start'}).catch(e=>toast(e.message));return}introUntil=Date.now()+5000;introKey=state.code+':'+p.id;stopBgm();playPlayerTheme(p);playIntroSfx(p.introEffect||'fx1');render();setTimeout(()=>{if(Date.now()<introUntil-100)return;introIndex++;runPlayerIntro()},5000)}
function countdown(){let rem=Math.max(1,Math.ceil((state.deadline-(Date.now()+offset))/1000));return `<div class="quiz-countdown"><div>${face()}</div><span>LEX SAYS GET READY</span><strong id="startCountdown">${rem}</strong><p>Quiz starting…</p></div>`}
function game(){let q=state.q,reveal=state.phase==='reveal',reading=state.phase==='reading';let own=state.players.find(p=>p.id===state.me?.id),buzzWinner=state.players.find(p=>p.id===state.buzz?.id),stealWinner=state.players.find(p=>p.id===state.pendingSteal?.winnerId);return `${roomBanner()}${lexLine()}<div class="game-layout"><div><section class="card question-card"><div class="question-meta"><span>${E.modes[q.mode].icon} ${esc(q.roundName)} · Round ${q.round}/${q.roundTotal}</span><span class="time" id="timer">${reading?'READ':'—'}</span></div><div class="timer-bar"><div class="timer-fill" id="timerFill"></div></div><p class="eyebrow" style="margin-top:23px">${esc(q.category)} · QUESTION ${q.position}/${q.roundSize}</p><h2 class="question-title">${esc(q.prompt)}</h2>${q.image?`<img class="question-image" id="questionImage" src="${esc(q.image)}" alt="Quiz picture">`:''}${q.audio&&(session.tv||session.hostToken)?`<audio id="songAudio" controls preload="auto" src="${esc(q.audio)}"></audio><p class="muted">Press play for this clip. Audio stays on this main device.</p>`:''}${state.paused?'<div class="notice">⏸ Quiz paused. Take a breather, buddy.</div>':''}${q.mode==='buzzer'&&state.phase==='question'&&buzzWinner&&state.buzz?.stage==='entrance'?`<div class="buzzer-event" role="status"><div class="fastest-kicker">🚨 BUZZED FIRST 🚨</div>${avatar(buzzWinner,true)}<strong>${esc(buzzWinner.name)}</strong><span>GET READY TO ANSWER</span></div>`:''}${state.phase==='reveal'&&state.firstCorrect&&!['music','buzzer'].includes(q.mode)&&Date.now()<fastestEventUntil?`<div class="fastest-event" role="status"><div class="spark-field">${Array.from({length:28},(_,i)=>`<i style="--i:${i}"></i>`).join('')}</div><div class="fastest-event-inner"><div class="fastest-kicker">${q.mode==='closest'?'🎯 CLOSEST ANSWER 🎯':'⚡ FASTEST CORRECT ⚡'}</div>${avatar(state.firstCorrect,true)}<strong>${esc(state.firstCorrect.name)}</strong><span>${q.mode==='closest'?'CLOSEST TO THE CORRECT NUMBER':'FIRST TO GET IT RIGHT'}</span><small>${q.mode==='closest'?'50 POINTS · 100 IF EXACT':'FULL POINTS!'}</small></div></div>`:''}<div class="play-area mode-${q.mode}">${answerArea()}</div>${reveal&&Date.now()>=fastestEventUntil?`<div class="reveal-box"><h3>${q.mode==='closest'?'The number was':'Correct answer'}</h3><strong>${esc(q.answer)}${q.mode==='higher'?' · Actual number: '+q.actual:''}${q.artist?' — '+esc(q.artist):''}</strong>${own?`<p>${own.answer?.correct?'You got it, buddy!':q.mode==='closest'?'Another guess was closer this time.':'Not this time, buddy.'}</p>`:''}${state.pendingSteal&&stealWinner?state.pendingSteal.winnerId===state.me?.id?`<div class="steal-choice"><h3>😈 ${esc(stealWinner.name)}, choose a team to steal from</h3><p class="muted">Scores stay hidden — pick by team name only.</p>${targetButtons('stealTarget',true)}<p class="steal-clock">⏳ <span id="stealTime">20</span>s to choose</p><button class="primary full" data-act="stealTarget">Lock in steal</button></div>`:`<div class="notice">😈 ${esc(stealWinner.name)} was first correct and is choosing a team to steal from…</div>`:''}</div>`:''}${controls()}<p class="progress-note">${state.index+1}/${state.total} total questions · ${state.players.filter(p=>p.submitted).length}/${state.players.length} answers locked</p></section></div><aside class="game-sidebar card"><div class="section-title" style="margin:0 0 16px"><h3 style="margin:0">Scores hidden</h3><span>🔒</span></div><p class="muted">No standings during the quiz. Final scores are revealed at the end.</p>${own?`<div class="divider"></div><p class="muted">Playing as <strong>${esc(own.name)}</strong></p>`:''}<button class="ghost full" data-act="enableVoice" style="margin-top:15px">${prefs.voice?'🔊 Voice on':'🎤 Hear Lex here'}</button></aside></div>`}
function finished(){let sorted=[...state.players].sort((a,b)=>b.score-a.score),career=storage.get('career',{games:0,wins:0,podiums:0,correct:0,answered:0,buzzWins:0,steals:0,bestScore:0,achievements:[]});let own=sorted.find(p=>p.id===state.me?.id);if(own&&lastSaved!==state.code){let rank=1+sorted.filter(p=>p.score>own.score).length;career.games++;career.wins+=rank===1?1:0;career.podiums+=rank<=3?1:0;career.correct+=own.correct||0;career.answered+=own.answered||0;career.buzzWins+=own.buzzWins||0;career.steals+=own.steals||0;career.bestScore=Math.max(career.bestScore,own.score||0);let ach=new Set(career.achievements||[]);if(rank===1)ach.add('Quiz Champion');if(rank<=3)ach.add('Podium Finisher');if((own.correct||0)>=10)ach.add('Quiz Brain');if((own.buzzWins||0)>=3)ach.add('Buzzer Beater');if((own.steals||0)>=10)ach.add('Stole the Show');career.achievements=[...ach];storage.set('career',career)}let own=sorted.find(p=>p.id===state.me?.id);if(own&&lastSaved!==state.code){let history=storage.get('history',[]),rank=1+sorted.filter(p=>p.score>own.score).length;let signature=state.code+':'+own.id;if(!history.some(h=>h.key===signature)){history.unshift({key:signature,date:new Date().toLocaleDateString('en-GB'),name:own.name,score:own.score,rank});storage.set('history',history.slice(0,30))}lastSaved=state.code}
const careerNow=storage.get('career',career||{});const award=(field)=>[...state.players].sort((a,b)=>b[field]-a[field])[0];return `${roomBanner()}${lexLine()}<div style="text-align:center"><span class="eyebrow">BRAGGING RIGHTS, SECURED</span><h1 style="font-size:52px">That’s a wrap, buddy.</h1><p class="lead" style="margin:auto">${sorted.filter(p=>p.score===sorted[0].score).length>1?'A shared crown!':'All hail '+esc(sorted[0].name)+'.'}</p></div><div class="podium">${sorted.slice(0,3).map((p,i)=>`<div class="podium-place">${avatar(p,true)}<div class="podium-block"><span>${['👑','🥈','🥉'][i]}</span><strong>${esc(p.name)}</strong><div class="score">${p.score}</div><p class="muted">${p.correct} correct</p></div></div>`).join('')}</div><div class="awards">${[['correct','⚡','Speed & Accuracy'],['steals','😈','Biggest Thief'],['correct','🧠','Quiz Brain']].map(([k,icon,title])=>`<div class="card award"><span class="icon">${icon}</span><h3 style="margin-top:12px">${title}</h3><strong>${award(k)[k]?esc(award(k).name):'No winner this time'}</strong><p class="muted">${award(k)[k]} ${k==='steals'?'points stolen':k==='correct'?'correct answers':'first buzzes'}</p></div>`).join('')}</div><div class="card career-card"><h2>📊 Career stats & achievements</h2><p class="muted">Games <strong>${careerNow.games||0}</strong> · Wins <strong>${careerNow.wins||0}</strong> · Podiums <strong>${careerNow.podiums||0}</strong> · Accuracy <strong>${careerNow.answered?Math.round((careerNow.correct||0)/careerNow.answered*100):0}%</strong> · Best score <strong>${careerNow.bestScore||0}</strong></p><div class="achievement-row">${(careerNow.achievements||[]).map(a=>`<span class="achievement">🏅 ${esc(a)}</span>`).join('')||'<span class="muted">Achievements unlock as you play.</span>'}</div></div><div class="card"><h2>Everyone’s results</h2>${leaderboard(true)}${session.hostToken?'<div class="actions"><button data-act="adjust">Correct a score</button></div>':''}</div><div class="actions" style="justify-content:center"><button class="gold" data-act="newQuiz">Another quiz? ↗</button><button data-act="copyResults">Copy results</button><button data-act="home">Home</button></div>`}
function playPlayerTheme(p){stopBgm();if(!p)return false;if(p.theme)return playTheme(p.theme);if(p.themePreset){playPresetTheme(p.themePreset);return true}return false}
function startFastestEvent(fc,fcKey){let finish=ms=>{ms=Math.max(5000,Math.min(10000,Math.round(ms||5000)));fastestEventUntil=Date.now()+ms;clearTimeout(fastestEventTimer);fastestEventTimer=setTimeout(()=>{if(fastestEventKey===fcKey){fastestEventUntil=0;if(themeAudio&&!themeAudio.paused)themeAudio.pause();syncBgm();render()}},ms);render()};fastestEventKey=fcKey;if(fc.theme){try{themeAudio=themeAudio||new Audio();themeAudio.pause();themeAudio.src=fc.theme;themeAudio.currentTime=0;themeAudio.volume=.85;themeAudio.load();themeAudio.muted=false;let go=()=>{let d=Number.isFinite(themeAudio.duration)?themeAudio.duration*1000:5000;finish(d);themeAudio.play().catch(()=>{})};if(themeAudio.readyState>=1)go();else{let fallback=setTimeout(()=>finish(5000),1200);themeAudio.onloadedmetadata=()=>{clearTimeout(fallback);go()}}}catch{finish(5000)}}else if(fc.themePreset&&themeSource(fc.themePreset)){try{themeAudio=themeAudio||new Audio();themeAudio.pause();themeAudio.src=new URL(themeSource(fc.themePreset),location.href).href;themeAudio.currentTime=0;themeAudio.volume=.85;themeAudio.load();themeAudio.muted=false;let go=()=>{let d=Number.isFinite(themeAudio.duration)?themeAudio.duration*1000:5000;finish(d);themeAudio.play().catch(()=>{})};if(themeAudio.readyState>=1)go();else{let fallback=setTimeout(()=>finish(5000),1200);themeAudio.onloadedmetadata=()=>{clearTimeout(fallback);go()}}}catch{finish(5000)}}else{finish(5000);if(fc.themePreset)playPresetTheme(fc.themePreset)}}
function render(){if(state&&page==='room'&&state.phase==='introductions'){let i=state.introIndex??0,p=state.players[i],k=state.code+':intro:'+i;if(p&&k!==introKey){introKey=k;stopBgm();playPlayerTheme(p)}}if(state&&page==='room'&&state.phase!=='introductions'&&introKey){introKey='';if(themeAudio&&!themeAudio.paused)themeAudio.pause();syncBgm()}if(state&&page==='room'){let fc=state.firstCorrect,fcKey=fc?state.index+':'+fc.id:'';if(fcKey&&fcKey!==render.lastFastest){render.lastFastest=fcKey;startFastestEvent(fc,fcKey)}let bw=state.q?.mode==='buzzer'&&state.buzz?.stage==='entrance'?state.players.find(p=>p.id===state.buzz.id):null,bk=bw?state.index+':'+bw.id:'';if(bk&&bk!==buzzerEventKey){buzzerEventKey=bk;buzzerEventPlaying=true;playPlayerTheme(bw)}if(!bk)buzzerEventPlaying=false}let oldAudio=$('#songAudio');let audioState=oldAudio?{src:oldAudio.getAttribute('src'),time:oldAudio.currentTime,playing:!oldAudio.paused}:null;let active=document.activeElement,focus=active?.id,selection=active?.selectionStart,values={};if(state&&['reading','question','reveal'].includes(state.phase))app.querySelectorAll('input,select').forEach(el=>{if(el.id)values[el.id]=el.value});
if(page==='join'&&/^[A-Z0-9]{6}$/.test(String(params.get('room')||'').toUpperCase())&&state?.code!==String(params.get('room')).toUpperCase())setTimeout(previewJoinRoom,0);
document.body.classList.toggle('tv',!!session?.tv);document.body.classList.toggle('quiz-active',page==='room'&&!!state&&['countdown','roundIntro','reading','question','reveal'].includes(state.phase));$('#connection').textContent=local?'SOLO DEMO':state?'● LIVE ROOM':backend?'● SERVER CONNECTED':'LET’S PLAY';app.innerHTML=page==='setup'?setup():page==='soloPlayers'?soloPlayersPage():page.startsWith('soloEdit:')?soloPlayerEditor(Number(page.split(':')[1])):page==='profile'?playerProfilePage():['join','tvjoin'].includes(page)?join():page==='room'&&state?(state.phase==='introductions'?playerIntro():state.phase==='lobby'?lobby():state.phase==='countdown'?countdown():state.phase==='roundIntro'?roundIntro():state.phase==='finished'?finished():game()):home();
Object.entries(values).forEach(([id,v])=>{let el=$('#'+id);if(el&&el.type!=='checkbox')el.value=v});if(focus&&$('#'+focus)){let el=$('#'+focus);el.focus({preventScroll:true});try{el.setSelectionRange(selection,selection)}catch{}}
let audio=$('#songAudio');if(audio&&audioState&&audioState.src===audio.getAttribute('src')){audio.currentTime=audioState.time;if(audioState.playing&&!state.paused&&state.phase==='question')audio.play().catch(()=>{})}if(audio&&(state.paused||state.phase!=='question'))audio.pause();updateTimer();syncBgm();requestAnimationFrame(startIntroCanvases);
if(state&&page==='room'){let key=state.phase+':'+state.index+':'+state.message,holdReveal=state.phase==='reveal'&&Date.now()<fastestEventUntil;if(!holdReveal&&key!==lastSpoken){lastSpoken=key;speak(state.message+(state.phase==='reading'?' '+state.q.prompt:''));if(state.phase==='reveal'&&state.me){let p=state.players.find(p=>p.id===state.me.id);beep(!!p?.answer?.correct)}}}
}
function updateTimer(){if(!state)return;let currentNow=Date.now()+offset;if(state.phase==='countdown'){let c=$('#startCountdown');if(c)c.textContent=Math.max(1,Math.ceil((state.deadline-currentNow)/1000));return}if(!state.q)return;let now=state.paused?state.pauseAt:Date.now()+offset;let rem=Math.max(0,(state.deadline-now)/1000);if($('#timer'))$('#timer').textContent=state.paused?'Ⅱ':state.phase==='reading'?'READ '+Math.ceil(rem):Math.ceil(rem)+'s';if($('#timerFill')){let max=state.phase==='reveal'?9:10;$('#timerFill').style.width=Math.min(100,rem/max*100)+'%'}if($('#buzzTime'))$('#buzzTime').textContent=Math.max(0,Math.ceil((state.buzz.until-now)/1000));if($('#stealTime')&&state.pendingSteal)$('#stealTime').textContent=Math.max(0,Math.ceil((state.pendingSteal.until-now)/1000));let img=$('#questionImage');if(img)img.style.filter=state.phase==='reveal'?'none':`blur(${Math.min(12,Math.max(0,rem-5)/2)}px)`}
async function request(path,method='GET',data=null,token=''){if(!backend)throw new Error('Connect the multiplayer server in ⚙ first, or try the solo demo.');let r=await fetch(backend+path,{method,headers:{...(data?{'Content-Type':'application/json'}:{}),...(token?{Authorization:'Bearer '+token}:{})},body:data?JSON.stringify(data):undefined,signal:AbortSignal.timeout(method==='GET'?20000:90000)});let out=await r.json();if(!r.ok)throw new Error(out.error||'The server could not complete that action.');return out}
function accept(s){offset=s.serverTime-Date.now();if(s.unchanged)return;let previousIndex=state?.index,previousPhase=state?.phase,previousIntro=state?.introIndex;state=s;networkFails=0;if(state.phase==='introductions'&&(previousPhase!=='introductions'||previousIntro!==state.introIndex)){window.scrollTo(0,0);introKey=''}if(previousIndex!==state.index)app.querySelectorAll('.answer-picked').forEach(x=>x.classList.remove('answer-picked'));render();if(local)storage.set('demo',local)}
async function poll(force=false){if(page!=='room'||!session||polling)return;polling=true;try{if(local){local.tick();runBots();let s=local.state(session.playerToken||session.hostToken);if(force||!state||s.version!==state.version)accept(s)}else{let out=await request('/api/rooms/'+session.code+(force?'':'?v='+(state?.version||0)),'GET',null,session.playerToken||session.hostToken);accept(out);$('#connection').textContent='● LIVE ROOM'}}catch(e){networkFails++;$('#connection').textContent='RECONNECTING…';if(force||networkFails===3)toast(e.message+' Your place is kept while we reconnect.')}finally{polling=false}}
function runBots(){if(!local||local.paused||Date.now()<botTimer)return;botTimer=Date.now()+1200;if(local.phase==='reveal'&&local.pendingSteal){let p=local.players.find(x=>x.bot&&x.id===local.pendingSteal.winnerId);if(p){local.pendingSteal.botChooseAt=local.pendingSteal.botChooseAt||Date.now()+1500+Math.floor(Math.random()*3500);if(Date.now()>=local.pendingSteal.botChooseAt){let ids=local.pendingSteal.targets||[],target=ids[Math.floor(Math.random()*ids.length)];if(target)try{local.steal(p.token,{target})}catch{}}}return}if(local.phase!=='question')return;let q=local.q();if(q.mode==='buzzer'){let bots=local.players.filter(p=>p.bot&&!p.answer);if(!local.buzz){let p=bots[Math.floor(Math.random()*bots.length)];if(p&&Math.random()<.45)try{local.buzzer(p.token)}catch{};return}let p=bots.find(x=>x.id===local.buzz?.id);if(p)try{let right=Math.random()<.62,letter=String(q.answer||'').trim().replace(/^the\s+/i,'').charAt(0).toUpperCase();local.answer(p.token,{value:right?letter:String.fromCharCode(65+Math.floor(Math.random()*26))})}catch{};return}local.players.filter(p=>p.bot&&!p.answer).forEach(p=>{try{if(q.mode==='music')return;let right=Math.random()<.62,letter=String(q.answer||'').trim().replace(/^the\s+/i,'').charAt(0).toUpperCase(),value=q.mode==='closest'?q.value+Math.floor(Math.random()*21)-10:q.mode==='bingo'?(right?q.answer:p.grid[Math.floor(Math.random()*9)]):q.mode==='higher'?(right?q.answer:q.options.find(x=>x!==q.answer)):q.mode==='buzzer'?letter:(right?letter:String.fromCharCode(65+Math.floor(Math.random()*26)));let target=local.players.find(x=>x.id!==p.id)?.id;local.answer(p.token,{value,stake:Math.min(100,p.score),target})}catch{}})}
async function action(kind,data={}){if(!session)return;if(kind==='answer'){if(answerSending||state?.me?.answer)throw new Error('Your answer is already locked.');answerSending=true;app.querySelectorAll('[data-act="answer"],[data-act="numberAnswer"],[data-act="musicAnswer"],[data-act="numKey"],[data-act="numBack"]').forEach(el=>el.disabled=true)}let token=kind==='host'?session.hostToken:session.playerToken;try{if(local){if(kind==='host')local.host(token,data);else if(kind==='answer')local.answer(token,data);else if(kind==='buzz')local.buzzer(token);else if(kind==='power')local.power(token,data);else if(kind==='steal')local.steal(token,data);await poll(true)}else{await request('/api/rooms/'+session.code+'/'+kind,'POST',data,token);await poll(true)}}finally{if(kind==='answer')answerSending=false}}
function setSession(s){session=s;storage.set('session',s)}
async function create(demo=false){readDraft();if(draft.hostPlays&&!profile.name)throw new Error('Enter your player name.');if(busy)return;busy=true;let config={...draft};try{let joined;
if(demo){let soloCount=Math.max(1,Math.min(100,soloRoster.length||Number(draft.soloPlayers)||8));if(!soloRoster.length)makeSoloRoster(soloCount);config.capacity=soloCount;local=new E.Game(config,'DEMO');let p=local.join({...soloRoster[0],name:soloRoster[0].name||'You'});for(let i=1;i<soloCount;i++){let bot=local.join({...soloRoster[i]});bot.bot=true}setSession({code:'DEMO',hostToken:local.hostToken,playerToken:p.token,demo:true,tv:false});storage.set('demo',local);joined=local.state(p.token)}else{let out=await request('/api/rooms','POST',config);local=null;setSession({code:out.code,hostToken:out.hostToken,playerToken:null,tv:false,server:backend});if(draft.hostPlays){let player=await request('/api/rooms/'+out.code+'/join','POST',profile);session.playerToken=player.token;storage.set('session',session);joined=player.state}else joined=out.state}
state=joined;page='room';lastSpoken='';render();window.scrollTo(0,0)
}catch(e){let target=$('#setupError');if(target)target.innerHTML=`<div class="notice error">${esc(e.message)}</div>`;else toast(e.message)}finally{busy=false}}
async function roomThemeClaims(force=false){let code=$('#roomCode')?.value.trim().toUpperCase()||state?.code||session?.code||String(params.get('room')||'').toUpperCase();if(!/^[A-Z0-9]{6}$/.test(code)||!backend)return new Set((state?.players||[]).map(p=>p.themePreset).filter(Boolean));try{let out=await request('/api/rooms/'+code);if(force||page==='join')state=out;return new Set((out.players||[]).map(p=>p.themePreset).filter(Boolean))}catch{return new Set((state?.players||[]).map(p=>p.themePreset).filter(Boolean))}}
async function assertThemeFree(id){if(!id)return;let used=await roomThemeClaims(true),mine=state?.me?.id&&state?.players?.find(p=>p.id===state.me.id)?.themePreset,ownClaim=globalThemeClaims.some(x=>x.themeId===id&&x.mine);if(!ownClaim&&id!==mine&&used.has(id))throw new Error('That theme is already taken by another player. Choose a different one.')}
async function previewJoinRoom(){let el=$('#roomCode'),code=el?.value.trim().toUpperCase();if(!/^[A-Z0-9]{6}$/.test(code)||!backend)return;try{let out=await request('/api/rooms/'+code);if(page==='join'&&$('#roomCode')?.value.trim().toUpperCase()===code){let pos=el.selectionStart;state=out;render();let fresh=$('#roomCode');if(fresh){fresh.value=code;fresh.focus({preventScroll:true});try{fresh.setSelectionRange(pos,pos)}catch{}}}}catch{}}
async function joinRoom(){let code=$('#roomCode')?.value.trim().toUpperCase();if(!/^[A-Z0-9]{6}$/.test(code))throw new Error('Enter the six-character room code.');let chosen=$('#themePreset')?.value||profile.themePreset;await refreshGlobalThemeClaims();if(claimedThemeSet().has(chosen))throw new Error('That theme is already claimed by another player. Choose a different one.');await assertThemeFree(chosen);saveProfile();await claimProfileTheme(chosen);let tv=page==='tvjoin';if(!tv&&!profile.name)throw new Error('Enter your player name.');busy=true;try{local=null;let out=tv?await request('/api/rooms/'+code):await request('/api/rooms/'+code+'/join','POST',profile);setSession({code,playerToken:tv?null:out.token,tv,server:backend});state=tv?out:out.state;page='room';lastSpoken='';render();window.scrollTo(0,0)}finally{busy=false}}
function invite(tv=false){let u=new URL(location.href);u.search='';u.hash='';u.searchParams.set('room',state.code);if(backend&&backend!==location.origin)u.searchParams.set('server',backend);if(tv)u.searchParams.set('view','tv');return u.href}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied, buddy!')}catch{let dlg=document.createElement('dialog');dlg.innerHTML='<h2>Copy this text</h2><textarea readonly></textarea><button>Close</button>';document.body.append(dlg);dlg.querySelector('textarea').value=text;dlg.querySelector('button').onclick=()=>{dlg.close();dlg.remove()};dlg.showModal();dlg.querySelector('textarea').select()}}
function openPhotoCrop(file,target){if(!file)throw new Error('Choose a picture first.');if(!/^image\/(jpeg|png|webp|heic|heif)$/i.test(file.type))throw new Error('Profile photos must be image files.');if(file.size>20*1024*1024)throw new Error('Choose an image below 20 MB.');let url=URL.createObjectURL(file),img=new Image();img.onload=()=>{let dlg=document.createElement('dialog');dlg.className='photo-crop-dialog';dlg.innerHTML=`<div class="crop-shell"><div><span class="eyebrow">POSITION YOUR PHOTO</span><h2>Make it fit perfectly.</h2><p class="muted">Drag the photo to move it. Pinch with two fingers or use the slider to zoom.</p></div><div class="crop-stage" id="cropStage"><img id="cropImage" alt="Photo being positioned"></div><label class="crop-zoom">Zoom<input id="cropZoom" type="range" min="1" max="4" step=".01" value="1"></label><div class="actions"><button type="button" class="primary" id="cropUse">Use Photo</button><button type="button" class="ghost" id="cropCancel">Cancel</button></div></div>`;document.body.append(dlg);let stage=dlg.querySelector('#cropStage'),pic=dlg.querySelector('#cropImage'),zoom=dlg.querySelector('#cropZoom'),scale=1,x=0,y=0,pointers=new Map(),lastDist=0,lastMid=null;pic.src=url;let base=()=>Math.max(stage.clientWidth/img.naturalWidth,stage.clientHeight/img.naturalHeight),clamp=()=>{let w=img.naturalWidth*base()*scale,h=img.naturalHeight*base()*scale;x=Math.max((stage.clientWidth-w)/2,Math.min((w-stage.clientWidth)/2,x));y=Math.max((stage.clientHeight-h)/2,Math.min((h-stage.clientHeight)/2,y))},paint=()=>{clamp();pic.style.width=(img.naturalWidth*base()*scale)+'px';pic.style.height=(img.naturalHeight*base()*scale)+'px';pic.style.transform=`translate(calc(-50% + ${x}px),calc(-50% + ${y}px))`};zoom.oninput=()=>{scale=Number(zoom.value);paint()};stage.addEventListener('pointerdown',e=>{stage.setPointerCapture(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY})});stage.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;let prev=pointers.get(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});let pts=[...pointers.values()];if(pts.length===1){x+=e.clientX-prev.x;y+=e.clientY-prev.y}else if(pts.length>=2){let a=pts[0],b=pts[1],dist=Math.hypot(a.x-b.x,a.y-b.y),mid={x:(a.x+b.x)/2,y:(a.y+b.y)/2};if(lastDist){scale=Math.max(1,Math.min(4,scale*dist/lastDist));zoom.value=scale;if(lastMid){x+=mid.x-lastMid.x;y+=mid.y-lastMid.y}}lastDist=dist;lastMid=mid}paint()});let up=e=>{pointers.delete(e.pointerId);if(pointers.size<2){lastDist=0;lastMid=null}};stage.addEventListener('pointerup',up);stage.addEventListener('pointercancel',up);let close=()=>{URL.revokeObjectURL(url);dlg.close();dlg.remove();photoCrop=null};dlg.querySelector('#cropCancel').onclick=close;dlg.addEventListener('cancel',e=>{e.preventDefault();close()});dlg.querySelector('#cropUse').onclick=()=>{let out=document.createElement('canvas');out.width=256;out.height=256;let c=out.getContext('2d'),b=base()*scale,w=img.naturalWidth*b,h=img.naturalHeight*b,left=(stage.clientWidth-w)/2+x,top=(stage.clientHeight-h)/2+y,ratio=256/stage.clientWidth;c.drawImage(img,left*ratio,top*ratio,w*ratio,h*ratio);let data=out.toDataURL('image/jpeg',.78);target(data);close()};photoCrop={dialog:dlg};dlg.showModal();requestAnimationFrame(paint)};img.onerror=()=>{URL.revokeObjectURL(url);throw new Error('Could not open that image.')};img.src=url}
async function fileData(file){return new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error('Could not read the file.'));r.readAsDataURL(file)})}
