app.addEventListener('change',async ev=>{let el=ev.target;try{if(el.id==='introEffect'){profile.introEffect=el.value;storage.set('profile',profile);refreshIntroEffectPreview(el.value);requestAnimationFrame(()=>playIntroSfx(el.value,true))}else if(el.id==='soloPhotoInput'){let i=Number(el.dataset.player),name=$('#soloName')?.value;if(name!=null)soloRoster[i].name=name;openPhotoCrop(el.files[0],data=>{soloRoster[i].photo=data;render()})}else if(el.id==='soloThemePreset'){let i=Number(el.dataset.player);soloRoster[i].themePreset=el.value;soloRoster[i].theme='';render()}else if(el.id==='soloThemeInput'){let i=Number(el.dataset.player),file=el.files[0];if(!file||!/^audio\//i.test(file.type))throw new Error('Theme songs must be audio files.');if(file.size>1000000)throw new Error('Keep your theme clip under 1 MB.');soloRoster[i].theme=await fileData(file);soloRoster[i].themePreset='';render()}else if(el.id==='photoInput'){saveProfile();openPhotoCrop(el.files[0],data=>{profile.photo=data;storage.set('profile',profile);if(page==='setup')readDraft();render()})}else if(el.id==='themePreset'){await refreshGlobalThemeClaims();if(claimedThemeSet().has(el.value))throw new Error('That theme is already claimed by another player. Choose a different one.');await assertThemeFree(el.value);saveProfile();profile.themePreset=el.value;profile.theme='';storage.set('profile',profile)}else if(el.id==='themeInput'){let file=el.files[0];if(!file)throw new Error('Choose an audio clip.');if(!/^audio\//i.test(file.type))throw new Error('Theme songs must be audio files.');if(file.size>1000000)throw new Error('Keep your theme clip under 1 MB.');saveProfile();profile.theme=await fileData(file);profile.themePreset='';await claimProfileTheme('');storage.set('profile',profile);render()}else if(el.dataset.round){readDraft();draft.rounds[Number(el.dataset.round)][el.dataset.key]=el.dataset.key==='count'?Number(el.value):el.value;render()}else if(el.id==='gameAuto')await action('host',{action:'auto',value:el.checked});else if(page==='setup')readDraft();else if(el.id==='playerName')saveProfile()}catch(e){toast(e.message)}});
